s_shared.coord_thread_posts WHERE workspace_id='papercusp-workspace' AND id IN (1161438,1161656) ORDER BY id","allowUnscoped":false,"maxRows":2},{"sql":"SELECT id,coord_owner_id,session_id,ended_at,ended_by,exit_code FROM harness_shared.adv_sessions WHERE workspace_id='papercusp-workspace' AND id IN (36434,36488) ORDER BY id","allowUnscoped":false,"maxRows":2}];const rs=await Promise.all(queries.map(q=>tools.dev.pg_query(q)));const input={expected,frames,ports:rs[0].rows,posts:rs[1].rows,targets:rs[2].rows};const program="import { createHash } from 'node:crypto';
