add('semantic-tamper-control',!verifySessionPortSeed(seed.replace('port-id: '+e.portId,'port-id: changed-'+e.portId),e.renderedHash),'A changed port-id byte in a private verification string must fail checksum verification.');
const receiptAt=seed.indexOf(String.fromCharCode(10,10)+'[PAPERCUSP SESSION PORT CHECKSUM');
add('receipt-removal-control',receiptAt>=0&&!verifySessionPortSeed(seed.slice(0,receiptAt),e.renderedHash),'Removing the complete terminal checksum receipt in a private verification string must fail verification.');
add('typed-post',post&&post.author_id===e.targetOwner&&post.thread_id==='work-item-thread-WI-10005889'&&post.body.includes(e.sourceNativeId)&&hash(post.body)===e.postHash,'Canonical original typed reply remains under its exact answering author, thread, source identity and body hash.');
add('target-endpoint',target&&target.coord_owner_id===e.targetOwner&&target.session_id===e.targetNativeId&&target.ended_by==='self'&&Number(target.exit_code)===0&&e.targetOwner!==e.sourceOwner,'Retained answering endpoint is the distinct exact native session and records self-end with exit zero.');
observations.push({bindingId:e.bindingId,portId:e.portId,source:{id:e.sourceId,backend:e.sourceBackend,nativeSessionId:e.sourceNativeId,ownerId:e.sourceOwner,sourceHash:e.sourceHash},target:{id:e.targetId,nativeSessionId:e.targetNativeId,ownerId:e.targetOwner,endedAt:target?.ended_at},indexedFrame:{ref:frame?.ref,chars:text.length,sha256:hash(text),seedSha256:hash(seed),rawNativeTranscriptBytesReobserved:false},post:{id:e.postId,authorId:post?.author_id,createdAt:post?.created_at,chars:post?.body.length,sha256:post?hash(post.body):null},renderedHash:e.renderedHash});}
