GF_VERIFY_RETAINED";const result=await tools.capability.bash({work_item_id:'WI-10005889',command});const finishedAt=new Date().toISOString();let verified;try{verified=JSON.parse(result.output);}catch{return {error:'verification-output-unreadable',result};}return {startedAt,finishedAt,exitCode:verified.exitCode,assertions:verified.assertions.map(a=>({id:a.id,passed:a.passed})),observations:verified.observations.map(o=>({bindingId:o.bindingId,frameSha256:o.indexedFrame.sha256,postSha256:o.post.sha256})),execution:{exitCode:result.exit_code,status:result.status}};
